import 'package:flutter/material.dart';
import 'package:flip_card_swiper/flip_card_swiper.dart';

void main() => runApp(MyApp());

class MyApp extends StatelessWidget {
  final List<Map<String, dynamic>> cards = [
    {'color': Colors.blue, 'text': 'Card 1'},
    {'color': Colors.red, 'text': 'Card 2'},
    {'color': Colors.green, 'text': 'Card 3'},
  ];

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        body: Center(
          child: FlipCardSwiper(
            cardData: cards,
            onCardChange: (i) {},
            cardBuilder: (context, index, visibleIndex) {
              final card = cards[index];
              return Container(
                key: ValueKey(index),
                width: 300,
                height: 200,
                decoration: BoxDecoration(
                  color: card['color'],
                  borderRadius: BorderRadius.circular(12),
                ),
                alignment: Alignment.center,
                child: Text(card['text'], style: const TextStyle(fontSize: 24, color: Colors.white)),
              );
            },
          ),
        ),
      ),
    );
  }
}
